Translate("esES", "un-goro-crater", {
	title = "Cráter de Un'Goro",
	aliases = { "Un'Goro", "el Cráter" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Cráter de Un'Goro es una vasta cuenca verde hundida en el sur de {link:kalimdor}Kalimdor{/link}, rodeada de acantilados entre las arenas de {link:tanaris}Tanaris{/link} y los páramos marchitos de {link:silithus}Silithus{/link}. Bajo su borde, el mundo parece pertenecer a otra era. El vapor sube de sus manantiales, un volcán humea en su corazón, y la selva está dominada por bestias que el resto del mundo olvidó hace mucho: demosaurios atronadores, estegodontes, pterrordáctilos alados y manadas de ravasaurios. Extraños cristales brillan en la hierba, y altas {link:crystal-pylons}torres de cristal{/link} se alzan al borde de la espesura.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica recoge cómo se formó el cráter, ni cuándo. Las historias de la era más antigua sostienen que los siervos de los {red:titans}titanes{/red} moldearon ciertas tierras del joven mundo como jardines de vida salvaje, y que Un'Goro fue una de ellas. Las {link:crystal-pylons}torres de cristal{/link} que se alzan en torno a su borde son más antiguas que cualquier pueblo que viva hoy en {link:kalimdor}Kalimdor{/link}, y ninguno de los que habitan ahora el cráter sabe decir quién las levantó ni por qué. Los {link:tauren}tauren{/link} que vienen aquí a cazar sienten con fuerza la presencia de la Madre Tierra en la cuenca. Para ellos, sus criaturas son los parientes más nobles de las bestias de sus propias llanuras.]=],
		},
		{
			title = "El presente",
			text = [=[El cráter ha atraído últimamente a una multitud de curiosos y de extraviados. Una compañía de exploradores dirigida por {link:williden-marshal}Williden Marshal{/link} vino a estudiar la tierra y estuvo a punto de ser destruida por ella. Sus supervivientes ocupan un refugio rocoso en las alturas del norte, donde se han reunido a su alrededor goblins de {link:gadgetzan}Gadgetzan{/link}, eruditos errantes y viajeros perdidos. El {link:cenarion-circle}Círculo Cenarion{/link} ha pedido tierra del cráter, de la que se dice que guarda una magia poderosa, y los druidas de {link:darnassus}Darnassus{/link} y de {link:thunder-bluff}Cima del Trueno{/link} la estudian. En el sur, los insectos de la colmena Gorishi han excavado en la tierra. Su presencia inquieta a los eruditos, porque nada semejante forma parte del orden natural del cráter. En estos días, los mapas nombran también dentro del cráter la {red:shaper-s-terrace}Shaper's Terrace{/red}, un lugar cuya historia se cuenta en su propia página.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los grandes saurios.{/b} Los demosaurios cazan por toda la cuenca. Los estegodontes pastan en el suroeste, los ravasaurios corren en manadas por el sureste y los diemetrodontes toman el sol a lo largo de sus senderos.
• {b}Los simios de la {link:fungal-rock}Roca Fungal{/link}.{/b} Grandes gorilas ocupan las cuevas del noreste y ahuyentan a cualquiera que se acerque.
• {b}Los Gorishi.{/b} Una colmena de insectos ha excavado {link:the-slithering-scar}La Cicatriz del Desliz{/link}, en el sur.
• {b}Elementales.{/b} Seres de llama viva recorren las laderas del volcán, y criaturas de alquitrán surgen de los pozos del norte.
• {b}Pétalos de sangre y mocos.{/b} Plantas carnívoras reptan por las espesuras del este, y los limos se reúnen en los pantanos.
• {b}Los recién llegados.{/b} Exploradores, manitas de {link:gadgetzan}Gadgetzan{/link} y vagabundos perdidos llenan el {link:marshal-s-refuge}Refugio de Marshal{/link}, y un cazador {link:tauren}tauren{/link} tiene su propio campamento donde el camino de {link:tanaris}Tanaris{/link} entra en el cráter.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}La era de los creadores.{/b} Las torres y los cristales del cráter son restos de un tiempo anterior a cualquier reino mortal. Ninguna historia mortal recoge cómo se levantaron.
• {b}La expedición Marshal.{/b} La compañía de {link:williden-marshal}Williden Marshal{/link} instaló campamentos en el suroeste y en el noreste del cráter. Las bestias arrasaron ambos, y los supervivientes huyeron al norte, a terreno más alto.
• {b}El presente.{/b} Eruditos, druidas, cazadores y al menos un vagabundo que no recuerda por qué vino buscan ahora el cráter.]=],
		},
		{
			title = "Saber del cráter",
			text = [=[• En el {link:marshal-s-refuge}Refugio de Marshal{/link} se dice que las torres y los cristales de colores de la hierba van juntos, y que la mezcla adecuada de colores despertará su poder.
• {link:krakle}Krakle{/link} de {link:gadgetzan}Gadgetzan{/link} cree que los {link:golakka-hot-springs}Baños de Golakka{/link} toman su calor del volcán, aunque todavía no ha terminado sus cálculos.
• {link:torwa-pathfinder}Torwa Pathfinder{/link} advierte que {link:lar-korwi}Lar'korwi{/link}, el gran ravasaurio del este, seguirá durante días a cualquiera que robe de su presa.]=],
		},
	},
})

Translate("esES", "marshal-s-refuge", {
	title = "Refugio de Marshal",
	sections = {
		{
			title = "Resumen",
			text = [=[El Refugio de Marshal es un campamento de tiendas y fuegos de cocina instalado entre las rocas de la pared norte del cráter. Se fundó en plena huida. Cuando las bestias de {link:un-goro-crater}Un'Goro{/link} arrasaron los campamentos de las Expediciones Marshal, {link:williden-marshal}Williden Marshal{/link} y su gente subieron a este terreno elevado, adonde los grandes saurios no podían seguirlos con facilidad. Desde entonces se les han unido otros: un maestro de vuelo de {link:gadgetzan}Gadgetzan{/link}, vagabundos perdidos, viajeros enemistados y una estudiosa de los cristales que trabaja en la cueva que hay sobre el campamento. El refugio es el único lugar del cráter donde un viajero puede dormir sin mantener un ojo abierto.]=],
		},
	},
})

Translate("esES", "fire-plume-ridge", {
	title = "Cresta del Penacho en Llamas",
	sections = {
		{
			title = "Resumen",
			text = [=[La Cresta del Penacho en Llamas es el volcán del centro de {link:un-goro-crater}Un'Goro{/link}, un cono calcinado que vierte humo y calor sobre todo el cráter. Sus laderas pertenecen a elementales de llama viva. En su corazón, en senderos de roca ennegrecida, habita {link:blazerunner}Blazerunner{/link}, un elemental envuelto en un aura que ninguna hoja ha atravesado. Guarda una cueva que contiene la Llama Dorada. El calor de la cresta es lo bastante feroz como para vencer a los incautos, y el explorador {link:ringo}Ringo{/link} estuvo a punto de morir por él. Quienes estudian el cráter creen que el volcán podría calentar sus manantiales.]=],
		},
	},
})

Translate("esES", "golakka-hot-springs", {
	title = "Baños de Golakka",
	aliases = { "Golakka" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Baños de Golakka humean en la parte occidental del cráter, una cadena de pozas cálidas en medio de la selva. {link:krakle}Krakle{/link}, un erudito de {link:gadgetzan}Gadgetzan{/link}, ha instalado su campamento junto a ellos, lejos de la seguridad del refugio. Quiere saber de dónde viene su calor, y sospecha del volcán de la {link:fire-plume-ridge}Cresta del Penacho en Llamas{/link}, no muy lejos al este. Sus mediciones lo han llevado a preguntarse por otros manantiales en la lejana {link:winterspring}Cuna del Invierno{/link}, donde no hay ningún volcán.]=],
		},
	},
})

Translate("esES", "lakkari-tar-pits", {
	title = "Fosas de Alquitrán Lakkari",
	aliases = { "Lakkari" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Fosas de Alquitrán Lakkari se encuentran en el norte del cráter, al sur del {link:marshal-s-refuge}Refugio de Marshal{/link}. Aquí el alquitrán negro brota del suelo en anchas pozas pegajosas. De él surgen criaturas de alquitrán que parecen vivir y moverse por voluntad propia. Las mayores, los señores del alquitrán, acechan cerca de las pozas del norte. Bestias y reptadores de alquitrán menores vagan más al sur, hacia las llanuras que hay bajo el volcán. Ningún registro dice quién dio nombre a las fosas.]=],
		},
	},
})

Translate("esES", "the-slithering-scar", {
	title = "La Cicatriz del Desliz",
	aliases = { "Cicatriz del Desliz" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Cicatriz del Desliz es una gran grieta en el suelo sur del cráter, donde los insectos Gorishi han construido su colmena. Las avispas llenan el aire sobre ella, y obreras, atracadoras y tuneladoras se arrastran por sus pasadizos. En cámaras profundas cubiertas de larvas, la colmena cría a sus jóvenes, y una reina los gobierna desde dentro. {link:hol-anyee-marshal}Hol'anyee Marshal{/link} estaba estudiando a los Gorishi cuando su expedición huyó. A sus ojos, no pertenecen en absoluto al cráter.]=],
		},
	},
})

Translate("esES", "terror-run", {
	title = "Camino del Terror",
	sections = {
		{
			title = "Resumen",
			text = [=[El Camino del Terror es la llanura del suroeste del cráter, y se ha ganado su nombre. Los estegodontes pastan por ella en pesadas manadas, y los demosaurios cazan entre ellos. Las Expediciones Marshal vinieron aquí a desenterrar los huesos de bestias muertas. Los excavadores descubrieron pronto que las vivas eran mucho más numerosas, y mucho más peligrosas. {link:spark-nilminer}Spark Nilminer{/link}, el jefe de excavación de la expedición, todavía habla del lugar con un temor manifiesto. Lo llama una trampa mortal, y no lo dice en broma.]=],
		},
	},
})

Translate("esES", "fungal-rock", {
	title = "Roca Fungal",
	sections = {
		{
			title = "Resumen",
			text = [=[La Roca Fungal es un hueco lleno de cuevas en el noreste del cráter, y es la guarida de los grandes simios de {link:un-goro-crater}Un'Goro{/link}. Gorilas, pisoteadores y atronadores la defienden, y ninguno es más feroz que el poderoso simio al que el cazador {link:tauren}tauren{/link} {link:torwa-pathfinder}Torwa{/link} llama {link:u-cha}U'cha{/link}. La inventora {link:karna-remtravel}Karna Remtravel{/link} envió a su simio mecánico {link:a-me-01}A-Me 01{/link} a estas cuevas para observar de cerca a los simios. Los simios no se dejaron engañar por mucho tiempo. Cuando unos viajeros la encontraron de nuevo, yacía en silencio y muy abollada a la entrada de las cuevas.]=],
		},
	},
})

Translate("esES", "the-marshlands", {
	title = "Los Pantanales",
	aliases = { "Pantanales" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Pantanales son las tierras bajas y húmedas del este del cráter, un país de barro, juncos y agua estancada. Limos de muchas clases se reúnen en sus pozas, y los pétalos de sangre reptan por sus espesuras. Uno de los campamentos abandonados de la expedición estaba a este lado del cráter, y sus provisiones quedaron intactas en el barro mucho después de que los exploradores huyeran. Una balsa destrozada descansa junto a un pequeño estanque más al sur, lejos de cualquier agua que hubiera podido llevarla hasta allí. Pertenecía al vagabundo {link:linken}Linken{/link}, aunque él ya no lo recordaba.]=],
		},
	},
})

Translate("esES", "crystal-pylons", {
	title = "Torres de cristal",
	aliases = { "torres de cristal", "las torres de Un'Goro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tres torres de cristal se alzan en la espesura del {link:un-goro-crater}Cráter de Un'Goro{/link}: una en el norte, otra contra la pared oriental y otra en el oeste. Son altas obras de piedra revestidas por dentro de cristal, y son mucho más antiguas que el campamento de cualquier explorador vivo. Durante mucho tiempo no fueron más que rumores que se contaban en el {link:marshal-s-refuge}Refugio de Marshal{/link}.]=],
		},
		{
			title = "Los cristales",
			text = [=[Cristales de colores yacen dispersos por el suelo del cráter: rojos, azules, amarillos y verdes. La mayoría de los viajeros no les hace caso. La gnoma {link:j-d-collie}J.D. Collie{/link} sí. Los reunió a sacos y probó todas las combinaciones que se le ocurrieron, pero no revelaron nada hasta que se encontraron las torres. Cuando los viajeros hubieron examinado las tres, ella estudió lo que habían visto y escribió sus conclusiones en un manual. Con él, los cristales podían fundirse en combinaciones que restauran, fortalecen, protegen y cargan de energía a quienes los llevan.]=],
		},
		{
			title = "Sin respuesta",
			text = [=[Quién levantó las torres, y con qué fin, el cráter no lo dice. {link:j-d-collie}J.D. Collie{/link} aprendió a usar sus cristales. No averiguó por qué estaban allí.]=],
		},
	},
})

Translate("esES", "williden-marshal", {
	title = "Williden Marshal",
	subtitle = "Líder de las Expediciones Marshal",
	found = "Refugio de Marshal, entre las tiendas",
	hint = [=[Hable con el líder de la expedición que se refugió en las alturas del norte del cráter.]=],
	allegiance = "Expediciones Marshal",
	aliases = { "Williden" },
	sections = {
		{
			title = "Resumen",
			text = [=[Williden Marshal dirige las Expediciones Marshal, una compañía de exploradores que no responde ante ninguna nación. Los trajo al {link:un-goro-crater}Cráter de Un'Goro{/link} para estudiarlo, y el cráter estuvo a punto de matarlos a todos. Ahora mantiene con vida a lo que queda de su gente en las alturas rocosas que llevan su nombre.]=],
		},
		{
			title = "Importancia",
			text = [=[Williden es la razón de que haya algún terreno seguro en el cráter. El refugio que su gente construyó en su huida se ha convertido en el punto de reunión de todos los que llegan a {link:un-goro-crater}Un'Goro{/link}, por elección o por desgracia. No finge que la expedición saliera bien. Admite que su compañía subestimó con mucho la ferocidad del cráter.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió la expedición que instaló campamentos en el suroeste y en el noreste del cráter.
• Cuando las bestias arrasaron ambos campamentos, guio a los supervivientes al norte, a terreno más alto.
• Pide a los viajeros que recuperen la comida y el equipo de investigación que su gente dejó atrás.
• Lleva un diario de la expedición, que se perdió en la huida.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ningún registro dice de dónde vino Williden ni cómo fundó su compañía. Esta entrada recoge solo lo que el cráter ha hecho de él.]=],
		},
	},
	chapters = {
		{
			title = "La salvación de la expedición",
			hint = "Recupere lo que la expedición abandonó en su huida.",
			text = [=[Los campamentos se habían abandonado con prisa, y con ellos se perdieron tanto la comida como los instrumentos de la expedición. Sin lo uno, los exploradores morirían de hambre. Sin lo otro, todo su sufrimiento habría sido en vano. Cuando ambas cosas volvieron al refugio, Williden declaró que la propia expedición se había salvado, y consideró a quien la salvó amigo de su compañía para toda la vida.]=],
		},
		{
			title = "El diario destrozado",
			hint = "Devuelva un diario perdido a su dueño.",
			text = [=[En la espesura se encontró un diario rasgado y pisoteado. Todavía podía leerse lo suficiente para contar la historia de la expedición: los campamentos arrasados, la huida, la búsqueda de terreno alto en el norte. Williden lo había contado entre las muchas cosas que el cráter le había arrebatado. Se alegró de recuperarlo.]=],
		},
	},
	mentions = {
		{ text = "La salvación de la expedición" },
		{ text = "El diario de Williden" },
	},
	bonds = {
		{ id = "hol-anyee-marshal", name = "Hol'anyee Marshal", note = "comparte su nombre y su expedición" },
		{ id = "spark-nilminer", name = "Spark Nilminer", note = "su jefe de excavación" },
	},
})

Translate("esES", "hol-anyee-marshal", {
	title = "Hol'anyee Marshal",
	subtitle = "Erudita de las Expediciones Marshal",
	found = "Refugio de Marshal, junto a Williden",
	hint = [=[Hable con la erudita de la expedición, que está junto a su líder.]=],
	allegiance = "Expediciones Marshal",
	aliases = { "Hol'anyee" },
	sections = {
		{
			title = "Resumen",
			text = [=[Hol'anyee Marshal es una erudita de las Expediciones Marshal. Antes de que la expedición huyera al norte, estaba estudiando a los insectos Gorishi del sur del cráter. La retirada no puso fin a su trabajo. Cree que los Gorishi son ajenos a la vida del cráter, y está decidida a averiguar cómo llegaron allí.]=],
		},
		{
			title = "Importancia",
			text = [=[Hol'anyee es la primera en decir en voz alta que la colmena Gorishi no pertenece a {link:un-goro-crater}Un'Goro{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudió a los Gorishi en el sur antes de que los campamentos fueran arrasados.
• Envió un vial raspador a la colmena para tomar una muestra de las paredes de sus criaderos.]=],
		},
	},
	mentions = {
		{ text = "Ecología alienígena" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "dirige la expedición" },
	},
})

Translate("esES", "spark-nilminer", {
	title = "Spark Nilminer",
	subtitle = "Jefe de excavación de las Expediciones Marshal",
	found = "Refugio de Marshal",
	hint = [=[Encuentre al excavador de la expedición, al que ya le queda poco amor por excavar.]=],
	allegiance = "Expediciones Marshal",
	aliases = { "Spark" },
	sections = {
		{
			title = "Resumen",
			text = [=[Spark Nilminer es el jefe de excavación de las Expediciones Marshal. Su tarea era desenterrar del {link:terror-run}Camino del Terror{/link} los huesos de estegodontes y diemetrodontes muertos. Las bestias vivas hicieron ese trabajo casi imposible, y Spark ha llegado a odiar el lugar. {link:williden-marshal}Williden{/link} y {link:hol-anyee-marshal}Hol'anyee{/link} todavía quieren sus huesos, y Spark prefiere no preguntar cómo se consiguen.]=],
		},
		{
			title = "Importancia",
			text = [=[Spark habla por los miembros corrientes de la expedición, que vinieron a trabajar y ahora solo quieren salir con vida.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue enviado a excavar en busca de huesos en el {link:terror-run}Camino del Terror{/link}.
• Acepta huesos de cualquier procedencia, y pide a los viajeros que no digan de dónde vienen.]=],
		},
	},
	mentions = {
		{ text = "Echar los huesos" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "su líder" },
	},
})

Translate("esES", "j-d-collie", {
	title = "J.D. Collie",
	subtitle = "Estudiosa de los cristales",
	found = "La cueva sobre el Refugio de Marshal",
	hint = [=[Busque a la gnoma que trabaja con cristales brillantes en la cueva que hay sobre el refugio.]=],
	allegiance = "Refugio de Marshal",
	aliases = { "J.D." },
	sections = {
		{
			title = "Resumen",
			text = [=[J.D. Collie es una gnoma que ha instalado su taller en la cueva que hay sobre el {link:marshal-s-refuge}Refugio de Marshal{/link}. Le fascinan los cristales de colores que hay por todas partes en {link:un-goro-crater}Un'Goro{/link} y los rumores sobre grandes torres en la espesura. Se cree casi cualquier historia que oye, y en el cráter esa confianza le ha servido sorprendentemente bien.]=],
		},
		{
			title = "Importancia",
			text = [=[J.D. es la primera en encontrar sentido a las {link:crystal-pylons}torres de cristal{/link}. Otros pasaron durante años junto a los cristales. Ella los reunió, los probó y por fin aprendió a unir su poder. También fue amable con el vagabundo {link:linken}Linken{/link} cuando llegó dando tumbos al refugio, y las pocas palabras que él le dijo en su confusión fueron la clave de su memoria.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reúne cristales de cuatro colores y los prueba en combinaciones interminables.
• Envía a los viajeros a buscar las torres del norte, del este y del oeste.
• Escribió un manual sobre las torres y los cristales.
• Orientó la búsqueda del pasado de {link:linken}Linken{/link} hacia {link:eridan-bluewind}Eridan Bluewind{/link}, en {link:felwood}Frondavil{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Las tres torres",
			hint = [=[Encuentre las torres de cristal de las que ha oído hablar J.D.]=],
			text = [=[Durante mucho tiempo, los experimentos de J.D. no dieron fruto, y empezó a temer que los cristales no tuvieran ningún poder. Entonces los viajeros encontraron las torres una a una: una en el norte, otra contra la pared oriental, otra en el oeste. Ella tomó lo que habían visto y lo estudió en su cueva. Cuando terminó, sabía cómo podían unirse los cristales, y lo dejó todo escrito en un libro.]=],
		},
		{
			title = "La memoria de una gnoma",
			hint = [=[Pregunte a la gnoma de los cristales lo que el vagabundo perdido le dijo una vez.]=],
			text = [=[Cuando {link:linken}Linken{/link} llegó por primera vez al refugio, estaba aturdido y no dejaba de murmurar cosas extrañas. J.D. recordaba una cosa que había dicho: que estaba fabricando un tótem, y que tenía que encontrar a alguien llamado {link:eridan-bluewind}Eridan Bluewind{/link} en {link:felwood}Frondavil{/link}. Era un hilo pequeño, pero llevó hasta {link:blazerunner}Blazerunner{/link}.]=],
		},
	},
	mentions = {
		{ text = "Cristales de poder" },
		{ text = "La torre del norte" },
		{ text = "La torre del este" },
		{ text = "La torre del oeste" },
		{ text = "Encontrarle sentido" },
		{
			text = [=[La ayuda de una gnoma, enviada por {link:linken}Linken{/link}]=],
		},
		{ text = "La memoria de {link:linken}Linken{/link}" },
		{ text = "Aquementas, el tótem que le llevaron" },
		{ text = "La aventura de {link:linken}Linken{/link}" },
	},
	bonds = {
		{ id = "linken", name = "Linken", note = "recordó lo que él olvidó" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "el nombre que pronunció Linken" },
