		{ text = "Una situación grave" },
		{ text = "La espada de Linken" },
		{ text = "La ayuda de una gnoma" },
		{ text = "Corazón de plata" },
		{ text = "Aquementas" },
		{ text = "La aventura de Linken" },
		{ text = "Es peligroso ir solo" },
	},
	bonds = {
