			text = [=[U'cha es el nombre que {link:torwa-pathfinder}Torwa Pathfinder{/link} da a un simio enorme de entre los gorilas de la {link:fungal-rock}Roca Fungal{/link}. El {link:tauren}tauren{/link} lo llama uno de los hijos más grandes de la Madre Tierra. De todos los simios del cráter, es el más fuerte. Habita en lo más hondo de las mismas cuevas donde fue derribada {link:a-me-01}A-Me 01{/link}, entre los gorilas, pisoteadores y atronadores que guardan la guarida.]=],
		},
		{
			title = "Importancia",
			text = [=[Enfrentarse a U'cha es, a ojos de {link:torwa-pathfinder}Torwa{/link}, la prueba de un gran cazador.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reina entre los gorilas de la {link:fungal-rock}Roca Fungal{/link}.]=],
		},
	},
	mentions = {
		{ text = "El poderoso U'cha" },
	},
	bonds = {
		{ id = "torwa-pathfinder", name = "Torwa Pathfinder", note = "le dio su nombre" },
	},
})

